#!/usr/bin/env bash
# Emit .ddp/docker-compose.yml from config.env. The compose file is generated
# because 10 client services differ only in name/ports/volume; edit this
# script, never the output. Run after changing config.env, and commit both.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
set -a; . "$HERE/config.env"; set +a
OUT="$HERE/../.ddp/docker-compose.yml"
mkdir -p "$(dirname "$OUT")"

PROFILE_FLAGS="--pprof.listen=0.0.0.0:6060 --pprof.blockprofilerate=$BLOCK_PROFILE_RATE --pprof.mutexprofilefraction=$MUTEX_PROFILE_FRACTION"

{
cat <<EOF
# GENERATED by bench/gen-compose.sh. Do not edit by hand.
#
# wavebench: 1 lumosd operator (postgres) + $NUM_CLIENTS waved clients
# (lwwallet/sqlite) + bitcoind/electrs/lnd support, all on regtest.
# Host ports are chosen to not collide with the tapbench network on the
# same machine. Nothing here auto-mines: the harness controls all blocks.

services:
  wb-bitcoind:
    image: $BITCOIND_IMAGE
    container_name: wb-bitcoind
    restart: unless-stopped
    command:
      - -regtest
      - -server=1
      - -rpcuser=devuser
      - -rpcpassword=devpass
      - -rpcallowip=0.0.0.0/0
      - -rpcbind=0.0.0.0
      - -txindex=1
      - -fallbackfee=0.00001
      - -addresstype=bech32m
      - -changetype=bech32m
      - -zmqpubrawblock=tcp://0.0.0.0:28332
      - -zmqpubrawtx=tcp://0.0.0.0:28333
    ports:
      - "127.0.0.1:19443:18443"
    volumes:
      # This image's entrypoint runs bitcoind with -datadir=/home/bitcoin/.bitcoin
      # (BITCOIN_DATA); mounting anywhere else leaves electrs reading an empty dir.
      - wb-bitcoind-data:/home/bitcoin/.bitcoin
    networks: [wavebench]
    healthcheck:
      test: ["CMD", "bitcoin-cli", "-regtest", "-rpcuser=devuser", "-rpcpassword=devpass", "getblockchaininfo"]
      interval: 5s
      timeout: 5s
      retries: 10

  # Esplora HTTP API over bitcoind's block files: the chain source every
  # lwwallet client polls. Reads the same volume bitcoind writes.
  wb-electrs:
    image: $ELECTRS_IMAGE
    container_name: wb-electrs
    restart: unless-stopped
    depends_on:
      wb-bitcoind:
        condition: service_healthy
    command:
      - -v
      - --timestamp
      - --network=regtest
      - --cookie=devuser:devpass
      - --daemon-rpc-addr=wb-bitcoind:18443
      - --http-addr=0.0.0.0:3002
      - --electrum-rpc-addr=0.0.0.0:60401
      - --cors=*
      - --daemon-dir=/home/user/.bitcoin
      - --db-dir=/electrs-db
    ports:
      - "127.0.0.1:13002:3002"
    volumes:
      - wb-bitcoind-data:/home/user/.bitcoin:ro
      - wb-electrs-data:/electrs-db
    networks: [wavebench]

  # The operator's on-chain wallet. Clients do not run lnd.
  wb-lnd:
    image: $LND_IMAGE
    container_name: wb-lnd
    restart: unless-stopped
    depends_on:
      wb-bitcoind:
        condition: service_healthy
    entrypoint:
      - lnd
      - --noseedbackup
      - --nobootstrap
      - --bitcoin.regtest
      - --bitcoin.node=bitcoind
      - --bitcoind.rpchost=wb-bitcoind
      - --bitcoind.rpcuser=devuser
      - --bitcoind.rpcpass=devpass
      - --bitcoind.zmqpubrawblock=tcp://wb-bitcoind:28332
      - --bitcoind.zmqpubrawtx=tcp://wb-bitcoind:28333
      - --rpclisten=0.0.0.0:10009
      - --restlisten=0.0.0.0:8080
      - --listen=0.0.0.0:9735
      - --tlsextradomain=wb-lnd
      - --debuglevel=info
    ports:
      - "127.0.0.1:11009:10009"
    volumes:
      - wb-lnd-data:/root/.lnd
    networks: [wavebench]
    healthcheck:
      test: ["CMD", "lncli", "--network=regtest", "getinfo"]
      interval: 5s
      timeout: 5s
      retries: 30

  wb-pg:
    image: $PG_IMAGE
    container_name: wb-pg
    restart: unless-stopped
    command:
      - postgres
      - -c
      - shared_preload_libraries=pg_stat_statements
      - -c
      - pg_stat_statements.max=10000
      - -c
      - pg_stat_statements.track=all
    environment:
      POSTGRES_USER: lightning
      POSTGRES_PASSWORD: lightning
      POSTGRES_DB: lumos
    ports:
      - "127.0.0.1:15432:5432"
    volumes:
      - wb-pg-data:/var/lib/postgresql/data
    networks: [wavebench]
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U lightning"]
      interval: 5s
      timeout: 5s
      retries: 10

  wb-lumosd:
    image: $LUMOS_IMAGE
    container_name: wb-lumosd
    # Stable hostname so the autocert TLS SAN covers the DNS name clients
    # dial; the default hostname is the container id, which changes on
    # every recreate and would invalidate the cert clients pin.
    hostname: wb-lumosd
    restart: unless-stopped
    depends_on:
      wb-lnd:
        condition: service_healthy
      wb-pg:
        condition: service_healthy
    command:
      - --network=regtest
      - --debuglevel=debug
      - --lnd.host=wb-lnd:10009
      - --lnd.tlspath=/lnd/tls.cert
      - --lnd.macaroonpath=/lnd/data/chain/bitcoin/regtest/admin.macaroon
      - --rpc.listen=0.0.0.0:7070
      - --adminrpc.listen=0.0.0.0:8081
      - --db.backend=postgres
      - --db.postgres.host=wb-pg
      - --db.postgres.port=5432
      - --db.postgres.user=lightning
      - --db.postgres.password=lightning
      - --db.postgres.dbname=lumos
      - --bitcoind.host=wb-bitcoind:18443
      - --bitcoind.user=devuser
      - --bitcoind.pass=devpass
      # v2: defaults are 200k/200k, too small for the 2M-per-client funding.
      - --rounds.maxvtxoamount=4000000
      - --rounds.maxuserbalance=8000000
      - --metrics.listen=0.0.0.0:9090
EOF
for f in $PROFILE_FLAGS; do echo "      - $f"; done
cat <<EOF
    ports:
      - "127.0.0.1:17070:7070"
      - "127.0.0.1:18085:8081"
      - "127.0.0.1:16060:6060"
      - "127.0.0.1:19090:9090"
    volumes:
      - wb-lnd-data:/lnd:ro
      - wb-lumosd-data:/root/.lumosd
    networks: [wavebench]
    healthcheck:
      test: ["CMD", "lumoscli", "info"]
      interval: 5s
      timeout: 5s
      retries: 30
EOF

for i in $(seq -w 1 "$NUM_CLIENTS"); do
cat <<EOF

  wb-client$i:
    image: $WAVED_IMAGE
    container_name: wb-client$i
    restart: unless-stopped
    depends_on:
      wb-lumosd:
        condition: service_healthy
    command:
      - --network=regtest
      - --debuglevel=debug
      - --wallet.type=lwwallet
      - --wallet.esploraurl=http://wb-electrs:3002
      # Default 30s; on a harness-mined chain that poll dominates every
      # confirmation wait. 5s matches what the upstream itests run with.
      - --wallet.pollinterval=5s
      - --wallet.password_file=/creds/wallet.pass
      - --server.host=wb-lumosd:7070
      - --server.tlscertpath=/lumosd/data/regtest/client-tls.cert
      - --server.macaroonpath=/lumosd/data/regtest/client.macaroon
      - --rpc.listenaddr=0.0.0.0:10029
      - --metrics.listen=0.0.0.0:9090
EOF
for f in $PROFILE_FLAGS; do echo "      - $f"; done
cat <<EOF
    ports:
      - "127.0.0.1:200$i:10029"
      - "127.0.0.1:161$i:6060"
      - "127.0.0.1:190$i:9090"
    volumes:
      - wb-client$i-data:/root/.waved
      - wb-lumosd-data:/lumosd:ro
      - ./../bench/creds:/creds:ro
    networks: [wavebench]
EOF
done

cat <<EOF

volumes:
  wb-bitcoind-data:
  wb-electrs-data:
  wb-lnd-data:
  wb-pg-data:
  wb-lumosd-data:
EOF
for i in $(seq -w 1 "$NUM_CLIENTS"); do echo "  wb-client$i-data:"; done
cat <<EOF

networks:
  wavebench:
    driver: bridge
EOF
} > "$OUT"

echo "wrote $OUT"
